#define assert(x) ((void)0)
#define MAX_DISK_OP_TRIES 300
#define SCE_SEEK_SET 0
#define SCE_SEEK_CUR 1
#define SCE_SEEK_END 2

static int g_error_condition;
static int g_try_count;

extern "C" int sceLseek(int, int, int);

class os_file
{
public:
  enum filepos_t
  {
    FP_BEGIN,
    FP_CURRENT,
    FP_END
  };

  int get_size();
  int set_fp(int pos, filepos_t base);

private:
  int name[2];
  int flags;
  int opened;
  int eof;
  int from_cd;
  union
  {
    int host;
    char cd[36];
  } io;
  int curr_fp;
};

__asm__(".equ get_size__7os_file, 0x001E0A48");
__asm__(".equ sceLseek, 0x003DED80");
__asm__(".equ g_error_condition, 0x003FE3A4");
__asm__(".equ g_try_count, 0x003FE3A8");

#define RETRY_LOOP_ENTRY g_try_count = 0; do{
#define RETRY_LOOP_WHILE(cond) g_error_condition = ((cond)); g_try_count++; }while( ( g_try_count < MAX_DISK_OP_TRIES ) && g_error_condition );
#define ON_RETRY_ERROR if( g_error_condition )

int os_file::set_fp( int pos, filepos_t base )
{
  int method = 0;
  int ret = -1;

  int size = get_size();

  switch( base )
  {
    case FP_BEGIN:
      curr_fp = pos;
      break;

    case FP_CURRENT:
      curr_fp += pos;
      break;

    case FP_END:
      curr_fp = size + pos;
      break;

    default:
      assert( 0 );
      break;
  }

  if( curr_fp > size ) curr_fp = size - 1;
  if( curr_fp < 0 ) curr_fp = 0;

  if( !from_cd )
  {
    switch ( base )
    {
      case FP_BEGIN:
        method = SCE_SEEK_SET;
        break;
      case FP_CURRENT:
        method = SCE_SEEK_CUR;
        break;
      case FP_END:
        method = SCE_SEEK_END;
        break;
    }
    RETRY_LOOP_ENTRY;
      ret = sceLseek(io.host, pos, method);
    RETRY_LOOP_WHILE( ret < 0 );

    ON_RETRY_ERROR{ eof = true; return -1; };
  }

  // could actually be true now, but chances are it will be false.
  eof = false;

  return ret;
}
